package com.bank.peekcount;

import java.util.*;
import java.util.logging.*;

public class PeekCountDemo {
    private static final Logger log = Logger.getLogger("PeekCount");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        PeekCountService service = new PeekCountService();

        log.info("SIZED + count() → peek SKIPPED (Java 9+):");
        long c1 = service.countWithPeek();            // prints nothing
        log.info(() -> "  count = " + c1);

        log.info("filter present → size unknown → peek RUNS:");
        long c2 = service.countWithPeekAndFilter();   // prints 1, 2, 3
        log.info(() -> "  count = " + c2);
    }
}

// ─── Would be in service/PeekCountService.java ───
class PeekCountService {
    // SIZED source + count() → count returns size without traversal → peek skipped
    long countWithPeek() {
        return Arrays.asList(1, 2, 3).stream()
            .peek(System.out::println)   // NOT printed in Java 9+
            .count();
    }

    // filter changes size → count must traverse → peek runs
    long countWithPeekAndFilter() {
        return Arrays.asList(1, 2, 3).stream()
            .peek(System.out::println)   // printed, because traversal happens
            .filter(n -> n > 0)
            .count();
    }
}
